#include <iostream>
#include <vector>
#include <numeric>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> stack;
    stack.reserve(n);

    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        if (x == 0) {
            if (!stack.empty()) {
                stack.pop_back();
            }
        } else {
            stack.push_back(x);
        }
    }

    long long sum = 0;
    for (int val : stack) {
        sum += val;
    }

    cout << sum << "\n";

    return 0;
}
